    SELECT 1 FROM profile p WHERE p.profaccref = a.accindex
    AND EXISTS (
        SELECT 1 FROM sessionbehavior s WHERE s.sessprofref = p.profkey
        AND EXISTS (
            SELECT 1 FROM contentbehavior c WHERE c.cntsessref = s.sessref
            AND EXISTS (
                SELECT 1 FROM messaginganalysis m WHERE m.msgcntref = c.cntref
            )
        )
    )
);

SELECT COUNT(*) FROM account a WHERE acctstatus = 'Dormant' AND EXISTS (
    SELECT 1 FROM profile p WHERE p.profaccref = a.accindex
    AND EXISTS (
        SELECT 1 FROM sessionbehavior s WHERE s.sessprofref = p.profkey
        AND EXISTS (
            SELECT 1 FROM networkmetrics n WHERE n.netsessref = s.sessref
            AND EXISTS (
                SELECT 1 FROM technicalinfo t WHERE t.technetref = n.netkey
                AND EXISTS (
                    SELECT 1 FROM securitydetection sd WHERE sd.sectechref = t.techkey
                )
            )
        )
    )
);

